function profileEditor(id){const v=S.configuration.profiles.find(v=>v.id===id)||{};S.editId=v.id||'';S.mapping=v.mapping_json?JSON.parse(v.mapping_json):[{header:'',field:'member_reference',value:''}];modal(`<h2 class="modal-title">Perfil de fichero bancario</h2><div class="notice warn">Copia el orden y las cabeceras del fichero que confirme el banco. No existe un formato universal.</div><div class="form-grid space-top">${field('Nombre del perfil','profile-name',v.name||'')}<div class="field"><label>Formato confirmado</label><select id="profile-format"><option value="csv">CSV</option><option value="xlsx" ${v.format==='xlsx'?'selected':''}>Excel XLSX</option></select></div><div class="field"><label>Separador CSV</label><select id="profile-delimiter"><option value=";">Punto y coma</option><option value="," ${v.delimiter===','?'selected':''}>Coma</option><option value="tab">Tabulador</option></select></div><div class="field"><label>Separador decimal CSV</label><select id="profile-decimal"><option value=",">Coma</option><option value="." ${v.decimal_separator==='.'?'selected':''}>Punto</option></select></div></div><h3 class="subheading">Columnas, en el orden del banco</h3><div id="mapping"></div>${btn('+ Añadir columna','add_column','ghost small')}${field('Referencia de la plantilla y confirmación bancaria','profile-reference',v.bank_reference||'','text','class="space-top"')}${check('profile-approved','Confirmo que el banco ha validado este mapeo.',false)}<div class="modal-footer">${S.boot.environment!=='production'?btn('Mapeo ficticio para probar','demo_mapping','ghost'):''}${btn('Guardar perfil','save_profile','primary')}</div>`);drawMapping();}
